const crypto = require('crypto');
const zlib = require('zlib');
const files = {};
for (const [index, item] of $input.all().entries()) {
  const name = item.binary?.data?.fileName;
  if (!name) continue;
  if (files[name] !== undefined) throw new Error('Duplicate input file: ' + name);
  files[name] = (await this.helpers.getBinaryDataBuffer(index, 'data')).toString('utf8');
