const source = JSON.parse(files['application.local.json'].replace(/^\uFEFF/, ''));
if (!source || Array.isArray(source) || typeof source !== 'object') throw new Error('Configuration must be a JSON object');
const keys = ['region', 'stack_name', 'compute_stack_name', 'frontend_ingress_cidr', 'instance_profile', 'frontend_instance_type', 'backend_instance_type', 'database_instance_type', 'backend_image', 'frontend_image', 'db_password_parameter', 'dockerhub_credentials_parameter', 'tls_parameter', 'server_name', 'athena_enabled', 'backend_memory'];
const config = Object.fromEntries(keys.map(key => [key, source[key]]));
const valid = (condition, message) => { if (!condition) throw new Error(message); };
valid(config.region === 'us-east-1', 'The base network requires us-east-1');
valid(typeof config.stack_name === 'string' && /^[a-zA-Z][a-zA-Z0-9-]{0,127}$/.test(config.stack_name), 'Invalid application stack name');
valid(!['network-stack', 'storage-stack', 'compute-stack', config.compute_stack_name].includes(config.stack_name), 'Use a dedicated application stack name');
valid(typeof config.athena_enabled === 'boolean', 'athena_enabled must be a boolean');
valid(typeof config.compute_stack_name === 'string' && /^[a-zA-Z][a-zA-Z0-9-]{0,127}$/.test(config.compute_stack_name), 'Invalid compute stack name');
const cidr = /^(\d{1,3}(?:\.\d{1,3}){3})\/(\d{1,2})$/.exec(config.frontend_ingress_cidr || '');
valid(cidr && cidr[1].split('.').every(n => Number(n) <= 255) && Number(cidr[2]) <= 32, 'Invalid frontend IPv4 CIDR');
valid(Number(cidr[2]) !== 0 || config.tls_parameter, 'Use a restricted CIDR for HTTP or configure TLS');
for (const key of ['backend_image', 'frontend_image']) valid(typeof config[key] === 'string' && /^docker\.io\/[a-z0-9_-]+\/[a-z0-9_.-]+@sha256:[0-9a-f]{64}$/.test(config[key]), key + ' must use a Docker Hub sha256 digest');
for (const key of ['frontend_instance_type', 'backend_instance_type', 'database_instance_type']) valid(['t2.small', 't2.medium', 't3.small', 't3.medium'].includes(config[key]), 'Unsupported instance type: ' + key);
valid(typeof config.instance_profile === 'string' && /^[\w+=,.@-]{1,128}$/.test(config.instance_profile), 'Invalid instance profile');
for (const key of ['db_password_parameter', 'dockerhub_credentials_parameter', 'tls_parameter']) {
