const bundle = zlib.gzipSync(Buffer.from(JSON.stringify({'remote_application.py': files['remote_application.py'], 'schema.sql': files['script-noctua.sql']}), 'utf8'));
return [{json: {config, template, packageBase64: bundle.toString('base64'), packageSha256: crypto.createHash('sha256').update(bundle).digest('hex'), runToken: 'noctua-' + crypto.randomUUID(), startedAt: Date.now(), deadline: Date.now() + 600000, phase: 'exports', ready: false, waitSeconds: 0, exports: [], parameterNames: [...new Set([config.db_password_parameter, config.dockerhub_credentials_parameter, config.tls_parameter].filter(Boolean))], parameterIndex: 0, analytics: {}}}];

const s = {...$json};
if (!Number.isFinite(s.deadline) || Date.now() > s.deadline) throw new Error('Infrastructure timeout in ' + s.phase + '; inspect CloudFormation/SSM before retrying');
const c = s.config;
let action, body = {}, service = 'cloudformation';
switch (s.phase) {
