  case 'analytics': action = 'DescribeStacks'; body.StackName = c.compute_stack_name; break;
  case 'validate': action = 'ValidateTemplate'; body.TemplateBody = s.template; break;
  case 'inspect': case 'stack': case 'collect': action = 'DescribeStacks'; body.StackName = c.stack_name; break;
  case 'plan': {
    action = 'CreateChangeSet';
    body = {StackName: c.stack_name, ChangeSetName: s.runToken, ChangeSetType: s.stackExists ? 'UPDATE' : 'CREATE', ClientToken: s.runToken, TemplateBody: s.template, Description: 'Noctua application stack and SSM deployment'};
    const mapping = {InstanceProfileName: 'instance_profile', FrontendIngressCidr: 'frontend_ingress_cidr', FrontendInstanceType: 'frontend_instance_type', BackendInstanceType: 'backend_instance_type', DatabaseInstanceType: 'database_instance_type'};
    const parameters = Object.entries(mapping).map(([ParameterKey, key]) => ({ParameterKey, ParameterValue: c[key]}));
    if (s.stackExists) for (const parameter of s.previousParameters || []) {
      if (!(parameter.ParameterKey in mapping)) parameters.push({ParameterKey: parameter.ParameterKey, UsePreviousValue: true});
    }
    parameters.forEach((parameter, index) => { for (const [key, value] of Object.entries(parameter)) body['Parameters.member.' + (index + 1) + '.' + key] = value; });
    break;
  }
  case 'changeset': case 'execution': action = 'DescribeChangeSet'; body.ChangeSetName = s.changeSetId; break;
  case 'execute': action = 'ExecuteChangeSet'; body = {ChangeSetName: s.changeSetId, ClientRequestToken: s.runToken}; break;
  case 'cleanup': action = 'DeleteChangeSet'; body.ChangeSetName = s.changeSetId; break;
  case 'online': service = 'ssm'; action = 'DescribeInstanceInformation'; body = {Filters: [{Key: 'InstanceIds', Values: s.instanceIds}]}; if (s.nextToken) body.NextToken = s.nextToken; break;
  default: throw new Error('Unknown infrastructure phase: ' + s.phase);
}
const encoded = service === 'ssm' ? JSON.stringify(body) : Object.entries({Action: action, Version: '2010-05-15', ...body}).map(([key, value]) => encodeURIComponent(key) + '=' + encodeURIComponent(String(value))).join('&');
return [{json: {...s, api: {service, action, body: encoded}}}];

// Transient HTTP failures may return HTML or an empty body instead of AWS XML.
const status = Number($json.statusCode ?? $json.status ?? 200);
const body = ('body' in $json) ? $json.body : $json;
return [{json: {body: status === 429 || status >= 500 ? '<Response/>' : body}}];

// The XML node replaces the entire JSON item; restore the HTTP envelope.
const resp = $('CloudFormation API').item.json;
const status = Number(resp.statusCode ?? resp.status ?? 200);
return [{json: {statusCode: status, body: $json}}];

// Normalize HTTP node output to an envelope {statusCode, body}.
const resp = $json;
const status = Number(resp.statusCode ?? resp.status ?? 200);
const body = ('body' in resp) ? resp.body : resp;
return [{json: {statusCode: status, body}}];

const s = {...$('Prepare infrastructure request').item.json, waitSeconds: 0};
if (Date.now() > s.deadline) throw new Error('Infrastructure timeout in ' + s.phase);
const list = value => value == null || value === '' ? [] : Array.isArray(value) ? value : [value];
const members = value => list(value?.member);
let body = $json.body || {};
body = body[s.api.action + 'Response'] || body.ErrorResponse || body;
const result = body[s.api.action + 'Result'] || body;
const error = body.Error || result.Error;
const kind = String(error?.Code || body.__type || '');
const message = String(error?.Message || body.message || body.Message || '');
const status = Number($json.statusCode);
const absent = s.phase === 'inspect' && status === 400 && kind === 'ValidationError' && message.includes('does not exist') && message.includes(s.config.stack_name);
const transient = status === 429 || status >= 500 || /Throttl|RequestLimitExceeded/.test(kind);
if (transient) {
  if (['execute', 'plan'].includes(s.phase)) throw new Error('AWS ' + kind + ' HTTP ' + status + '; inspect change set ' + (s.changeSetId || s.runToken) + ' before retrying');
  return [{json: {...s, waitSeconds: 10}}];
}
if (!absent && (kind || !Number.isFinite(status) || status < 200 || status >= 300)) throw new Error('AWS ' + kind + ' HTTP ' + status + ': ' + message + ' (phase ' + s.phase + ')');
const go = (phase, seconds = 0, timeout) => { s.phase = phase; s.waitSeconds = seconds; delete s.nextToken; if (timeout) s.deadline = Date.now() + timeout; };
const stack = () => { const values = members(result.Stacks); if (values.length !== 1) throw new Error('Expected exactly one stack in ' + s.phase); return values[0]; };
const out = data => Object.fromEntries(members(data.Outputs).map(item => [item.OutputKey, item.OutputValue]));
const healthy = data => ['CREATE_COMPLETE', 'UPDATE_COMPLETE'].includes(data.StackStatus);
switch (s.phase) {
  case 'exports': {
    s.exports = [...s.exports, ...members(result.Exports)];
    if (result.NextToken) { s.nextToken = result.NextToken; break; }
    const missing = ['VPC-ID', 'PUBLIC-SUBNET', 'PRIVATE-BACKEND', 'PRIVATE-DB'].filter(name => !s.exports.some(item => item.Name === name));
    if (missing.length) throw new Error('Base network exports missing: ' + missing.join(', '));
    if (s.exports.some(item => String(item.ExportingStackId || '').includes(':stack/' + s.config.stack_name + '/'))) throw new Error('Application stack must not be an existing network/export stack');
    go('secrets'); break;
  }
  case 'secrets': {
    const name = s.parameterNames[s.parameterIndex];
    const parameter = list(result.Parameters).find(item => item.Name === name);
    // DescribeParameters is best-effort and can return empty pages with NextToken.
    if (!parameter && result.NextToken) { s.nextToken = result.NextToken; break; }
    if (!parameter) throw new Error('Create the SecureString parameter before deploying: ' + name);
    if (parameter.Type !== 'SecureString') throw new Error('Parameter must be SecureString: ' + name);
    delete s.nextToken;
    s.parameterIndex++;
    if (s.parameterIndex >= s.parameterNames.length) go(s.config.athena_enabled ? 'analytics' : 'validate');
    break;
  }
  case 'analytics': {
    const data = stack(); s.analytics = out(data);
    if (!healthy(data) || !s.analytics.GlueDatabaseName || !s.analytics.AthenaWorkGroupName) throw new Error('Healthy compute stack must provide GlueDatabaseName and AthenaWorkGroupName');
