    s.stackExists = !!data && data.StackStatus !== 'REVIEW_IN_PROGRESS';
    s.previousParameters = s.stackExists ? members(data.Parameters) : [];
    s.infrastructureAction = s.stackExists ? 'UPDATE' : 'CREATE';
    go('plan'); break;
  }
  case 'plan':
    if (!result.Id || !result.StackId) throw new Error('CloudFormation did not return change set and stack IDs');
    s.changeSetId = result.Id; s.stackId = result.StackId; go('changeset', 10, 600000); break;
  case 'changeset':
