      s.changes = members(result.Changes); go('execute');
    } else if (['CREATE_PENDING', 'CREATE_IN_PROGRESS'].includes(result.Status)) s.waitSeconds = 10;
    else throw new Error('Unexpected change set status: ' + result.Status + '/' + result.ExecutionStatus);
    break;
  case 'execute': go('stack', 10, 2400000); break;
  case 'stack': {
