    if (new Set(s.instanceIds).size !== 3 || s.instanceIds.some(id => !/^i-[a-f0-9]{8,17}$/.test(id))) throw new Error('Invalid or duplicate instance IDs');
    for (const key of ['FrontendPublicIp', 'BackendPrivateIp', 'DatabasePrivateIp']) if (!/^\d{1,3}(?:\.\d{1,3}){3}$/.test(values[key]) || values[key].split('.').some(n => Number(n) > 255)) throw new Error('Invalid IP output: ' + key);
